/// <summary>
/// Exclude selected line from pricing query
/// </summary>
/// <param name = "_parentTableId">Reference to related parent table</param>
/// <param name = "_parentRecId">Reference Id of related parent record</param>
/// <param name = "_refTableId">Reference table Id of selected line</param>
/// <param name = "_refRecId">Reference record Id of selected line</param>
static public void excludeLine(RefTableId _parentTableId, RefRecId _parentRecId, RefTableId _refTableId, RefRecId _refRecId )
{
    UPSPricingAttributeLineState pricingAttributeLineState;

    ttsbegin;

    if (_parentTableId && _parentRecId && _refTableId && _refRecId)
    {
        pricingAttributeLineState = UPSPricingAttributeLineState::find(_parentTableId, _parentRecId, _refTableId, _refRecId, true);

        pricingAttributeLineState.ParentTableId = _parentTableId;
        pricingAttributeLineState.ParentRecId   = _parentRecId;
        pricingAttributeLineState.LineTableId   = _refTableId;
        pricingAttributeLineState.LineRecId     = _refRecId;
        pricingAttributeLineState.LineType      = UPSPricingAttributeLineType::Exclude;

        pricingAttributeLineState.write();
    }

    ttscommit;
}

/// <summary>
/// Include selected line to pricing query
/// </summary>
/// <param name = "_parentTableId">Reference to related parent table</param>
/// <param name = "_parentRecId">Reference Id of related parent record</param>
/// <param name = "_refTableId">Reference table Id of selected line</param>
/// <param name = "_refRecId">Reference record Id of selected line</param>
static public void includeLine(RefTableId _parentTableId, RefRecId _parentRecId, RefTableId _refTableId, RefRecId _refRecId )
{
    UPSPricingAttributeLineState pricingAttributeLineState;

    ttsbegin;

    if (_parentTableId && _parentRecId && _refTableId && _refRecId)
    {
        delete_from pricingAttributeLineState
            where pricingAttributeLineState.ParentTableId   == _parentTableId
                && pricingAttributeLineState.ParentRecId    == _parentRecId
                && pricingAttributeLineState.LineTableId    == _refTableId
                && pricingAttributeLineState.LineRecId      == _refRecId;
    }

    ttscommit;
}

/// <summary>
/// Find <c>UPSPricingAttributeLineState</c> record
/// </summary>
/// <param name = "_parentTableId">Reference to related parent table</param>
/// <param name = "_parentRecId">Reference Id of related parent record</param>
/// <param name = "_refTableId">Reference table ID</param>
/// <param name = "_refRecId">Reference record Id</param>
/// <param name = "_forUpdate">For update parameter</param>
/// <returns><c>UPSPricingAttributeLineState</c> record</returns>
static public UPSPricingAttributeLineState find(RefTableId _parentTableId, RefRecId _parentRecId, RefTableId _refTableId, RefRecId _refRecId, boolean _forUpdate = false)
{
    UPSPricingAttributeLineState pricingAttributeLineState;

    if (_parentTableId && _parentRecId && _refTableId && _refRecId)
    {
        pricingAttributeLineState.selectForUpdate(_forUpdate);

        select firstonly pricingAttributeLineState
            where pricingAttributeLineState.ParentTableId   == _parentTableId
                && pricingAttributeLineState.ParentRecId    == _parentRecId
                && pricingAttributeLineState.LineTableId    == _refTableId
                && pricingAttributeLineState.LineRecId      == _refRecId;
    }

    return pricingAttributeLineState;
}

/// <summary>
/// Clear related line state records
/// </summary>
/// <param name = "_parentTableId">Parent table Id</param>
/// <param name = "_parentRecId">Parent record Id</param>
public static void clearLineState(RefTableId _parentTableId, RefRecId _parentRecId)
{
    UPSPricingAttributeLineState pricingAttributeLineState;

    ttsbegin;

    delete_from pricingAttributeLineState
        where pricingAttributeLineState.ParentTableId == _parentTableId
            && pricingAttributeLineState.ParentRecId == _parentRecId;

    ttscommit;
}
